# Checks that S has both upper- and lowercase letters and all its characters are distinct
S = input()
if any(c.isupper() for c in S) and any(c.islower() for c in S) and len(set(S)) == len(S):
  print("Yes")
else:
  print("No")

# Checks S for mixed case and compares its set of characters directly against len(S) to reject repeated letters
S = input()
if S.upper() != S and S.lower() != S and len(set(S)) == len(S):
  print("Yes")
else:
  print("No")

